// A basic conditional type
// If T is a string, become 'true'. Else, become 'false'.
type IsString<T> = T extends string ? true : false;

type A = IsString<"Hello">; // true
type B = IsString<123>;     // false

// A real-world Distributive Conditional Type
// Removes all 'null' or 'undefined' from a union type
type NonNullableCustom<T> = T extends null | undefined ? never : T;

type ValidData = NonNullableCustom<string | null | number>;
// Distributes to:
// (string extends null? no -> string)
// (null extends null? yes -> never)
// (number extends null? no -> number)
// Final Result: string | number
